          </p>
        ) : (
          <div className="broker-profile-health-plot min-w-0 w-full overflow-hidden [&_svg]:overflow-hidden!">
            <ParentSize className="h-full min-h-0 w-full" debounceTime={10}>
              {({ width, height }) => {
                const innerHeight = resolveHealthPlotInnerHeight(height, CHART_MARGIN_Y);
